import itertools

# Define the size of the grid
n = 12

# Generate all permutations of the numbers 0 through n-1
perms = list(itertools.permutations(range(n)))

# Initialize an empty grid
grid = [[0]*n for _ in range(n)]

# Iterate over all possible permutations for each row
for p in perms:
    # Check if the permutation can be used as a row in the grid
    if all(p[i] != i for i in range(n)):
        # If the permutation can be used, fill in the rest of the grid
        for i in range(n):
            for j in range(n):
                grid[i][j] = p[j]
        # Check if the grid satisfies the QG3 property
        qg3_satisfied = True
        for i in range(n):
            for j in range(n):
                if grid[grid[i][j]][grid[j][i]] != i:
                    qg3_satisfied = False
                    break
            if not qg3_satisfied:
                break
        # If the grid satisfies the QG3 property, print it and stop
        if qg3_satisfied:
            print([num for row in grid for num in row])
            break
